// Créer un objet indexé par ID pour un accès rapide par jour
export const CHALLENGE_DETAILS: Record<number, ChallengeDetails> = challenges.reduce((acc, challenge) => {
  acc[challenge.id] = challenge;
  return acc;
}, {} as Record<number, ChallengeDetails>);

/**
 * Récupère les détails d'un défi par jour (1-365)
 */
export function getChallengeDetailsForDay(dayOfYear: number): ChallengeDetails | null {
  return CHALLENGE_DETAILS[dayOfYear] || null;
}

/**
 * Récupère tous les défis d'une catégorie
 */
export function getChallengesByCategory(categorie: ChallengeDetails['categorie']): ChallengeDetails[] {
  return challenges.filter(c => c.categorie === categorie);
}

/**
 * Récupère tous les défis d'un niveau
 */
export function getChallengesByDifficulty(difficulte: ChallengeDetails['difficulte']): ChallengeDetails[] {
  return challenges.filter(c => c.difficulte === difficulte);
}

/**
 * Récupère le nombre total de défis
 */
export function getTotalChallenges(): number {
  return challenges.length;
}

/**
 * Récupère le numéro du jour dans l'année (1-365/366)
 * Méthode simple qui évite les problèmes de timestamps et changements d'heure
 * @returns Le numéro du jour
 */
export function getDayOfYear(): number {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  const day = now.getDate();
  
  let dayCount = 0;
  
  // Jours dans chaque mois
  const daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  
  // Ajuster pour année bissextile
  if ((year % 4 === 0 && year % 100 !== 0) || year % 400 === 0) {
    daysInMonth[1] = 29;
  }
  
  // Compter les jours des mois complets
  for (let i = 0; i < month; i++) {
    dayCount += daysInMonth[i];
  }
  
  // Ajouter les jours du mois actuel
  return dayCount + day;
}